import{_ as t,o as l,c as i,a2 as a}from"./chunks/framework.D5wUhsuj.js";const k=JSON.parse('{"title":"Agent 经验与 Skill 自进化","description":"","frontmatter":{},"headers":[],"relativePath":"zh/05-agent-experience-and-skill-evolution.md","filePath":"zh/05-agent-experience-and-skill-evolution.md"}'),o={name:"zh/05-agent-experience-and-skill-evolution.md"};function s(n,e,d,r,c,p){return l(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="agent-经验与-skill-自进化" tabindex="-1">Agent 经验与 Skill 自进化 <a class="header-anchor" href="#agent-经验与-skill-自进化" aria-label="Permalink to &quot;Agent 经验与 Skill 自进化&quot;">​</a></h1><blockquote><p>文档版本：1.0.0。本文描述基于 AgentTask record 的 Agent 校验、经验、Lesson 与 Skill 演化链。</p></blockquote><h2 id="_1-目标与边界" tabindex="-1">1. 目标与边界 <a class="header-anchor" href="#_1-目标与边界" aria-label="Permalink to &quot;1. 目标与边界&quot;">​</a></h2><p>PhyAgentOS 在任务/工作流粒度学习，而不是从某一次孤立 tool call 直接学习。一个已经终结并具有语义验证结果的 AgentTask 及其全部 PlanRevision 可以形成一个 <code>TaskEpisode</code>，后台反思再用它支持可复用 Skill 工作流或作用域 Lesson。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill 激活</span></span>
<span class="line"><span>  → AgentTask + PlanRevisions + ToolInvocations</span></span>
<span class="line"><span>  → 任务语义结果</span></span>
<span class="line"><span>  → 去敏 TaskEpisode</span></span>
<span class="line"><span>  → 后台异步反思</span></span>
<span class="line"><span>      ├─ 可复用成功工作流 → SkillCandidate</span></span>
<span class="line"><span>      └─ 工作流相关失败   → FailureObservation → LessonCluster</span></span></code></pre></div><p>该链路不修改 AgentTask 状态、Forge Tool calls、Gateway payload、证据采集、recovery 顺序或下层执行。初始化、持久化、模型调用、校验或写入失败时，evolution fail-open，原任务结果保持不变。</p><p>首个 outcome provider 是 Forge。<code>TaskOutcomeSource</code> 协议允许后续 Runtime 产生相同 <code>TaskOutcomeEnvelope</code>，而无需修改 Lesson 或 Skill 演化逻辑。</p><h2 id="_2-skill-激活与任务归因" tabindex="-1">2. Skill 激活与任务归因 <a class="header-anchor" href="#_2-skill-激活与任务归因" aria-label="Permalink to &quot;2. Skill 激活与任务归因&quot;">​</a></h2><p><code>agents.evolution.enabled=true</code> 时，Agent 上下文包含 Skill 摘要，并要求在首次工具调用前检查匹配项。匹配的工作流通过以下工具激活：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>activate_skill(name, role=&quot;primary&quot; | &quot;supporting&quot;)</span></span></code></pre></div><p>激活规则：</p><ul><li><code>name</code> 必须是精确注册的 hyphen-case Skill 名称，不能传路径；</li><li>同名时 workspace Skill 优先于 installed 与 built-in Skill，installed Skill 优先于 built-in；</li><li>unavailable Skill 不能激活；</li><li>每个 turn 最多一个 primary，可有多个 supporting Skill；</li><li>同一 Skill 不能在 turn 内切换 role；</li><li>只有 primary Skill 可被自动更新；</li><li>primary 与 supporting Skill 都可以接收相关失败归因；</li><li>通过文件工具读取 <code>SKILL.md</code> 不算激活。</li></ul><p>返回值包含完整 Skill 文档、activation ID、来源、内容 digest 和适用的 active Lesson。Digest 将归因固定到当前 turn 实际使用的 revision；新晋升 revision 从后续 turn 的 summary 开始可见。</p><p>AgentLoop 记录有序工具名和参数字段名，不记录参数值。Forge AgentTask 要求本轮 primary activation；创建时重新校验并冻结精确 Skill 版本、Runtime、manifest/工作流 hash 与所需 ToolSpec。后续绑定 Query/Action/Session records 与 Gateway invocation references 随执行加入；无任务诊断 Query 不归因到 task episode。</p><p>Binding 同时冻结每个已激活 Skill 当时返回的适用 active Lesson。自动验证、后续 PlanRevision 和 review 都按 task ID 解析 Lesson 上下文，因此即使经验账本后来变化，也使用同一组有界内容。这些 Lesson 只是非权威工作流建议：可以提示检查点，但不能确定 criterion 状态、替代执行事实或证据，也不能作为 evidence reference。没有激活 Skill 的任务传入空 Lesson 集合。</p><h2 id="_3-outcome-与-episode-分类" tabindex="-1">3. Outcome 与 Episode 分类 <a class="header-anchor" href="#_3-outcome-与-episode-分类" aria-label="Permalink to &quot;3. Outcome 与 Episode 分类&quot;">​</a></h2><p><code>AgentTaskOutcomeSource</code> 读取已持久化 AgentTask，生成：</p><ul><li>去敏后的 goal 与 criteria；</li><li>最终 semantic verdict 和逐 criterion 状态；</li><li>每个 PlanRevision 的 Query/Action/Session semantics、input 字段名、execution status、verdict 与去敏 reason；</li><li>不透明 task、revision、invocation、attempt 与 evidence fingerprint；</li><li>primary/supporting activations 与去敏 workflow trace。</li></ul><p>学习内容不复制原始工具输出、input 值、evidence locator、endpoint、凭据、绝对路径或可执行 Gateway ID。Task、revision、invocation 与 attempt identity 只保留为内部不透明 reference，不能进入生成的 Lesson 或 Skill。</p><p>Outcome 策略：</p><table tabindex="0"><thead><tr><th style="text-align:left;">结果</th><th style="text-align:left;">经验行为</th></tr></thead><tbody><tr><td style="text-align:left;">最终 <code>success</code>，所有 criterion <code>satisfied</code></td><td style="text-align:left;">可支持可复用 Skill candidate</td></tr><tr><td style="text-align:left;">最终 <code>failure</code> 或 <code>replan_required</code></td><td style="text-align:left;">可产生工作流相关 failure observation</td></tr><tr><td style="text-align:left;">失败/replan revision 后最终成功</td><td style="text-align:left;"><code>mixed</code>：可同时支持 recovery 工作流和失败 observation</td></tr><tr><td style="text-align:left;"><code>inconclusive</code>、非法 verdict、Verifier/服务错误</td><td style="text-align:left;">只诊断，不产生可晋升经验</td></tr><tr><td style="text-align:left;"><code>verification=off</code></td><td style="text-align:left;">不进行语义学习</td></tr><tr><td style="text-align:left;">人工 review</td><td style="text-align:left;">不生成新的 episode 或支持计数</td></tr></tbody></table><p>数据库对 AgentTask 设置唯一约束，因此 PlanRevision、重复 completion event、进程 replay 和 review attempt 始终属于同一个 episode 与同一个独立支持单位。</p><h2 id="_4-后台反思" tabindex="-1">4. 后台反思 <a class="header-anchor" href="#_4-后台反思" aria-label="Permalink to &quot;4. 后台反思&quot;">​</a></h2><p>Coordinator 同步创建 episode 与 pending job，再以 <code>asyncio</code> task 运行模型反思。进程重启后，中断 job 恢复为 pending；临时失败按有限策略重试，最终失败保持可观察，但不影响 Forge。</p><p>反思模型接收结构化去敏 episode、active candidates、active Lessons、Lesson clusters 和注册 Skill catalog。任务文本、trace、verdict 文本与 evidence label 都被明确视为不可信数据。响应必须通过 <code>experience_assessment_v1</code> 校验。</p><p>Evolution 调用使用独立的 <code>maxEvolutionCallsPerRun</code>，不占 <code>maxVerifierCallsPerRun</code>。预算耗尽时延后 pending work，而不是把任务改成失败。</p><h2 id="_5-lesson-相关性与-observation" tabindex="-1">5. Lesson 相关性与 Observation <a class="header-anchor" href="#_5-lesson-相关性与-observation" aria-label="Permalink to &quot;5. Lesson 相关性与 Observation&quot;">​</a></h2><p>失败或 replan attempt 不会自动等价为 Skill 失败。每个 observation proposal 都带 <code>LessonEligibility</code>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">Decision/reason</th><th style="text-align:left;">处理</th></tr></thead><tbody><tr><td style="text-align:left;"><code>related / workflow_related</code></td><td style="text-align:left;">可规范化并进入聚类</td></tr><tr><td style="text-align:left;"><code>unrelated / task_unsatisfiable</code></td><td style="text-align:left;">只记录诊断</td></tr><tr><td style="text-align:left;"><code>unrelated / verifier_limit</code></td><td style="text-align:left;">只记录诊断</td></tr><tr><td style="text-align:left;"><code>unrelated / evidence_limit</code></td><td style="text-align:left;">只记录诊断</td></tr><tr><td style="text-align:left;"><code>unrelated / external_or_infrastructure</code></td><td style="text-align:left;">只记录诊断</td></tr><tr><td style="text-align:left;"><code>unrelated / user_constraint</code></td><td style="text-align:left;">只记录诊断</td></tr><tr><td style="text-align:left;"><code>uncertain / unknown</code></td><td style="text-align:left;">只记录诊断</td></tr></tbody></table><p>符合条件的 <code>FailureObservation</code> 包含可用时的 Skill 绑定、workflow key、canonical pattern key、泛化 pattern summary、<code>applies_when</code>、<code>does_not_apply_when</code> 与 recovery principle。它不得包含某次任务的具体答案、对象名称/值、坐标、选项、endpoint、Gateway ID、原始 input 或工具输出。</p><p>未激活 Skill 时，observation 保持在 unbound cluster。后续 Skill candidate 的精确 workflow-key 匹配可以绑定该 cluster；不同 workflow 不会合并。</p><h2 id="_6-lesson-聚类与激活" tabindex="-1">6. Lesson 聚类与激活 <a class="header-anchor" href="#_6-lesson-聚类与激活" aria-label="Permalink to &quot;6. Lesson 聚类与激活&quot;">​</a></h2><p>反思模型优先匹配同 Skill、同 workflow 的现有 cluster；否则根据 Skill/unbound 作用域、workflow key 和规范化 pattern key 派生稳定 cluster identity。首期不使用 embedding 或向量数据库。</p><p>Cluster 状态：</p><table tabindex="0"><thead><tr><th style="text-align:left;">状态</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>collecting</code></td><td style="text-align:left;">独立 AgentTask 少于 <code>minLessonEpisodes</code>，或反证后重新打开</td></tr><tr><td style="text-align:left;"><code>blocked</code></td><td style="text-align:left;">合成、抽象或内容校验失败</td></tr><tr><td style="text-align:left;"><code>activated</code></td><td style="text-align:left;">已存在通过校验的 <code>ScopedLesson</code></td></tr></tbody></table><p>支持计数在 <code>(cluster_id, root_task_id)</code> 上唯一，其中稳定 root reference 标识 AgentTask。默认 <code>minLessonEpisodes=3</code> 时，前两次相关失败保持 collecting，第三个不同 task 才调度合成。</p><p>合成模型只接收 cluster 中的规范化 observations。Lesson proposal 必须包含：</p><ul><li>明确适用与不适用条件；</li><li>不随任务变化的 failure mode；</li><li>可复用检查、决策原则或恢复建议；</li><li>可选的同作用域 superseded Lessons。</li></ul><p>激活必须同时通过：</p><ol><li>静态内容策略；</li><li><code>lesson_abstraction_validation_v1</code>：<code>reusable=true</code>、<code>contains_specific_answer=false</code>、无 <code>unsupported_literals</code> 且置信度至少 <code>0.8</code>。</li></ol><p>静态策略拒绝凭据、endpoint、绝对路径、可执行 ID、Action Manifest 副本、固定 action/input、绕过验证指令、prompt injection、答案/选项表达、坐标与固定数值答案。拒绝后 cluster 保持 blocked，永不进入 Agent 上下文。</p><h2 id="_7-scoped-lesson-检索与生命周期" tabindex="-1">7. Scoped Lesson 检索与生命周期 <a class="header-anchor" href="#_7-scoped-lesson-检索与生命周期" aria-label="Permalink to &quot;7. Scoped Lesson 检索与生命周期&quot;">​</a></h2><p>Active <code>ScopedLesson</code> 记录：</p><ul><li>Skill 与 workflow 作用域；</li><li><code>applies_when</code> 与 <code>does_not_apply_when</code>；</li><li>failure mode、recommendation 与 severity；</li><li>cluster 与 supporting episode IDs；</li><li>observation count 和 counterexample lineage；</li><li><code>active</code>、<code>inactive</code>、<code>superseded</code> 或 <code>retired</code> 状态。</li></ul><p><code>activate_skill</code> 只查询绑定到该 Skill 的 active Lesson。轻量 term-overlap 评分会比较当前 task summary 与适用/排除文本，再按更强重叠、更多 observations 与更新时间排序，最多返回 <code>maxLessonsPerSkill</code> 条。Unbound、collecting、blocked、inactive、superseded 与 retired 内容都不注入。</p><p>更窄且通过校验的新 Lesson 只能 supersede 同 Skill/workflow 作用域内的 active Lesson。成功 episode 可以标记直接反证的 active Lesson；达到配置的独立成功门槛后，该 Lesson retired，cluster 重新打开以接收更窄证据。</p><p>稳定安全约束保存在 operator 管理的 <code>AGENTS.md</code> 或 <code>EMBODIED.md</code>；evolution 不写入这些文件。</p><h2 id="_8-skill-candidate-与受控晋升" tabindex="-1">8. Skill Candidate 与受控晋升 <a class="header-anchor" href="#_8-skill-candidate-与受控晋升" aria-label="Permalink to &quot;8. Skill Candidate 与受控晋升&quot;">​</a></h2><p>语义成功或成功恢复且可复用的 episode 可以创建或合并 <code>SkillCandidate</code>。Candidate 按 Skill 名和 workflow key 聚合；近义重复应复用现有 Skill/candidate。</p><p>晋升规则：</p><ul><li>每个 AgentTask episode 最多支持一次；</li><li>默认 <code>minSuccessfulEpisodes=3</code>，需要三个独立成功；</li><li>update 必须指向已激活 primary Skill；</li><li>已有 primary Skill 的任务不能创建替代 Skill；</li><li>同 workflow active Lesson 和反思 conflict 会阻止晋升；</li><li>结构、内容策略与 reload 校验必须通过。</li></ul><p>Learned workflow 内容只允许 trigger/description、preconditions、通用 steps、verification checkpoints、recovery guidance 与 applicability boundaries。禁止 scripts、assets、Action Manifest 副本、固定 Gateway action/ID、endpoint、凭据和绕过 Forge/Verifier 的指令。</p><p>新 Skill 写入 <code>workspace/skills/&lt;name&gt;/SKILL.md</code>，且 <code>always: false</code>。更新已有 workspace Skill 时保留人工正文，只替换标记区块：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- paos:learned-workflow:start --&gt;</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>&lt;!-- paos:learned-workflow:end --&gt;</span></span></code></pre></div><p>Built-in Skill 永不原地修改：基线先归档，再复制为 workspace override，强制非 always-on，然后加入 managed block。写入使用原子替换，旧 workspace revision 归档，随后从 workspace reload；任何失败都会回滚原文件。</p><h2 id="_9-持久化与投影" tabindex="-1">9. 持久化与投影 <a class="header-anchor" href="#_9-持久化与投影" aria-label="Permalink to &quot;9. 持久化与投影&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;workspace&gt;/.paos/evolution/</span></span>
<span class="line"><span>├── experience.sqlite3</span></span>
<span class="line"><span>└── revisions/&lt;skill&gt;/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;workspace&gt;/skills/&lt;skill&gt;/</span></span>
<span class="line"><span>├── SKILL.md</span></span>
<span class="line"><span>└── references/LESSONS.md</span></span></code></pre></div><p><code>experience.sqlite3</code> 是事实源，采用 SQLite WAL，保存 binding、episode、reflection job、observation、cluster、AgentTask 唯一支持、cluster job、scoped Lesson、candidate、event 和 migration metadata。</p><p><code>references/LESSONS.md</code> 为人工审阅原子生成，分开展示 active/历史 Lesson 与 collecting/blocked cluster，并显示独立支持与校验状态。人工修改该投影不会改变事实源。</p><p>根目录 <code>LESSONS.md</code> 保留。Evolution 首次启动时，将旧 <code>- Lesson:</code> 条目一次性导入为 inactive、unbound record。启用 evolution 时，根目录文件既不是全局 Agent context，也不作为 Forge Verifier 输入。数据库中 pre-cluster active Lesson 也会降级，并依据已知 source roots 重建；只有重新合成和校验后才能 active。关闭 evolution 会恢复原来的全局 Agent context、Verifier 输入和 Verifier append 行为，但不删除 evolution 数据。</p><h2 id="_10-可观测性与扩展" tabindex="-1">10. 可观测性与扩展 <a class="header-anchor" href="#_10-可观测性与扩展" aria-label="Permalink to &quot;10. 可观测性与扩展&quot;">​</a></h2><p>结构化事件包括 episode created、assessment completed、eligibility rejected、observation clustered、cluster supported/blocked/activated、Lesson superseded/retired、candidate supported/blocked/promoted、validation rejected、budget deferred、built-in baseline archived 和 revision rolled back。运行日志使用 ID 与有限摘要，不记录原始敏感值。</p><p>接入另一个可信任务 outcome provider 时：</p><ol><li>实现 <code>TaskOutcomeSource.build(task_ref)</code>；</li><li>返回包含 semantic verdict、criteria、lineage 与不透明引用的 <code>task_outcome_envelope_v1</code>；</li><li>保持 AgentTask 级幂等与去敏；</li><li>通过 <code>ExperienceCoordinator</code> 调度 completion；</li><li>不把 provider 私有执行字段放入 Lesson 或 Skill 契约。</li></ol><p>该边界允许其他可信任务 provider 复用 Lesson 聚类与 Skill 晋升，而无需修改 Forge Tool API。</p><h2 id="后续阅读" tabindex="-1">后续阅读 <a class="header-anchor" href="#后续阅读" aria-label="Permalink to &quot;后续阅读&quot;">​</a></h2><ul><li><a href="/docs/zh/01-framework-introduction">框架介绍</a></li><li><a href="/docs/zh/02-user-manual">用户手册</a></li><li><a href="/docs/zh/03-developer-manual">开发者手册</a></li><li><a href="/docs/zh/04-forge-configuration-reference">Forge 配置参考</a></li><li><a href="/docs/">文档索引</a></li></ul>`,67)])])}const g=t(o,[["render",s]]);export{k as __pageData,g as default};
